public enum GameState { Menu, Playing, Paused, GameOver }
public GameState currentState;

void Update()
{
    switch (currentState)
    {
        case GameState.Menu:
            ShowMenu();
            break;
        case GameState.Playing:
            HandleInput();
            break;
        case GameState.Paused:
            break;
        case GameState.GameOver:
            ShowGameOver();
            break;
    }
}
